class Config {
  private static instance: Config | null = null;
  private constructor(public readonly values: Record<string,string>) {}
  static getInstance(): Config {
    if (!Config.instance) Config.instance = new Config({});
    return Config.instance;
  }
  get(key: string) { return this.values[key]; }
}

export class ServiceRegistry {
  private static services = new Map<string, any>();
  static register(name: string, svc: any) { this.services.set(name, svc); }
  static get<T>(name: string): T { return this.services.get(name); }
}

