class LoggerA {
  private static instance: LoggerA | null = null;
  private constructor() {}
  static getInstance(): LoggerA {
    if (!LoggerA.instance) LoggerA.instance = new LoggerA();
    return LoggerA.instance;
  }
  log(msg: string) { console.log(msg); }
}

